mapper.update:
update reader
set borrowed_count = borrowed_count + #{delta}
where id = #{id} and borrowed_count + #{delta} >= 0

mapper.select:
select * from reader
and (full_name like concat('%', #{keyword}, '%') or student_id like concat('%', #{keyword}, '%') or class_name like concat('%', #{keyword}, '%'))
order by id desc limit #{limit} offset #{offset}
